function ChapterBridge.NavToId(csEnv, id)
    
    local go = nil
    ChapterUtils.ProcessChapter(id, function(g)
        KTool.SetActive(csEnv.DirectorControl.gameObject, false)
        go = g
    end, function()
        KTool.SafeDelete(go)
        csEnv:ChapterFinish()
    end)
    
    
end

function ChapterBridge.PlaySoundById(notification)

    local soundId = notification.soundId
    printInfo("play %s", soundId)
    if notification.isStop then
        CriWareUtils.StopById(soundId)
        return
    end
    if notification.isBGM then
        CriWareUtils.PlayMusicById(soundId)
    else
        CriWareUtils.PlaySeById(soundId, ChapterBridge.GetSpeaker(notification.speaker))
    end
    
    
end

function ChapterBridge.GetSpeaker(speaker)
    if string.isEmpty(speaker) then
        return
    end

    local lips =  GameObject.FindObjectsOfType(typeof(CS.CriWare.CriLipsDeformerForAtomSource))
    
    for i = 1, lips.Length do
        local tmp = lips[i - 1].gameObject.name
        printInfo("%s %d", tmp, tostring(speaker))
        if string.contains(tmp, tostring(speaker)) or string.contains(tostring(speaker), tmp) then
            return lips[i - 1].gameObject
        end
    end
    
    
end

